/**
 * THE PARITY GATE.
 *
 * The TS engine must reproduce the Python engine's numbers on identical
 * inputs to 6 decimal places (Python rounds most stats to 4dp, so this is
 * exact-match). Fixtures are generated by tools/extract_parity_fixtures.py
 * and guarded on the Python side by tests/test_parity_fixtures.py — the two
 * engines cannot silently diverge.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import {
  computeAgreement,
  fleissKappa,
  iccOneway,
  normalizeUnitName,
  type AgreementPackView,
  type KeywordRule,
} from "../src/engine/agreement.js";
import {
  bannedElementsGate,
  runGate,
  termLintGate,
  wordCountGate,
} from "../src/engine/gates.js";
import {
  checkShipGates,
  computeScores,
  priorityScore,
  BLOCKING_BUILTINS,
  type ScoringPackView,
} from "../src/engine/scoring.js";
import { sequenceRatio } from "../src/engine/seqmatch.js";
import { sanitizeControlChars, stripFences } from "../src/engine/sanitize.js";
import {
  estimatePipelineCost,
  estimatePerLoopUsd,
  estimateTotalUsd,
} from "../src/engine/costs.js";
import { assembleForPersona } from "../src/engine/assembly.js";
import type { DocumentModel, ManifestEntry } from "../src/engine/manifest.js";

const PARITY_DIR = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "..",
  "fixtures",
  "parity",
);

function loadFixture<T>(name: string): T {
  return JSON.parse(fs.readFileSync(path.join(PARITY_DIR, name), "utf-8")) as T;
}

/** Fixture NaN sentinel → NaN. */
function num(v: number | "NaN"): number {
  return v === "NaN" ? NaN : v;
}

function expectParity(actual: number, expected: number | "NaN", label: string): void {
  const exp = num(expected);
  if (Number.isNaN(exp)) {
    expect(actual, label).toBeNaN();
  } else {
    expect(actual, label).toBeCloseTo(exp, 6);
  }
}

interface PackJson {
  score_dimensions: string[];
  verdict_field: string;
  verdict_categories: string[];
  unit_field: string;
  unit_list_field: string;
  unit_score_field: string | null;
  unit_keyword_rules: [string, string][];
  ship_gates?: {
    composite_min: number;
    dimension_min: number;
    weights: Record<string, number> | null;
    composite_exclude_personas: string[];
    blocking: string | null;
  };
}

function agreementPack(pack: PackJson): AgreementPackView {
  return {
    scoreDimensions: pack.score_dimensions,
    verdictField: pack.verdict_field,
    verdictCategories: pack.verdict_categories,
    unitField: pack.unit_field,
    unitListField: pack.unit_list_field,
    unitScoreField: pack.unit_score_field,
    unitKeywordRules: pack.unit_keyword_rules as KeywordRule[],
  };
}

function scoringPack(pack: PackJson): ScoringPackView {
  const ship = pack.ship_gates!;
  return {
    scoreDimensions: pack.score_dimensions,
    unitField: pack.unit_field,
    unitListField: pack.unit_list_field,
    unitScoreField: pack.unit_score_field,
    unitKeywordRules: pack.unit_keyword_rules as KeywordRule[],
    shipGates: {
      compositeMin: ship.composite_min,
      dimensionMin: ship.dimension_min,
      weights: ship.weights,
      compositeExcludePersonas: ship.composite_exclude_personas,
      blockingFindings:
        ship.blocking === null ? null : BLOCKING_BUILTINS[ship.blocking]!,
    },
  };
}

describe("agreement parity", () => {
  interface Case {
    name: string;
    pack: PackJson;
    reviews: Record<string, unknown>[];
    personas: string[] | null;
    expected: Record<string, number | "NaN">;
  }
  const cases = loadFixture<Case[]>("agreement_cases.json");
  it.each(cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const result = computeAgreement(c.reviews, agreementPack(c.pack), c.personas);
    expect(Object.keys(result).sort()).toEqual(Object.keys(c.expected).sort());
    for (const [key, exp] of Object.entries(c.expected)) {
      expectParity(result[key]!, exp, key);
    }
  });
});

