describe("scoring + ship-gate parity", () => {
  interface Case {
    name: string;
    pack: PackJson;
    reviews: Record<string, unknown>[];
    personas: string[];
    synthesis: Record<string, unknown> | null;
    gate_results: Record<string, { passed: boolean; findings: string[] }>;
    expected: {
      composite: number | "NaN" | null;
      per_dimension: Record<string, number>;
      ship_ok: boolean;
      reasons: string[];
    };
  }
  const cases = loadFixture<Case[]>("scoring_cases.json");
  it.each(cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const pack = scoringPack(c.pack);
    const personas = c.personas.length > 0 ? c.personas : null;
    const { composite, perDimension } = computeScores(c.reviews, pack, personas);
    if (c.expected.composite === null) {
      expect(composite).toBeNull();
    } else {
      expectParity(composite!, c.expected.composite, `${c.name}:composite`);
    }
    expect(Object.keys(perDimension).sort()).toEqual(
      Object.keys(c.expected.per_dimension).sort(),
    );
    for (const [dim, exp] of Object.entries(c.expected.per_dimension)) {
      expectParity(perDimension[dim]!, exp, `${c.name}:${dim}`);
    }

    const check = checkShipGates({
      synthesis: c.synthesis,
      reviews: c.reviews,
      gateResults: c.gate_results,
      pack,
      personas,
    });
    expect(check.ok, `${c.name}:ship_ok`).toBe(c.expected.ship_ok);
    expect(check.reasons, `${c.name}:reasons`).toEqual(c.expected.reasons);
  });
});

describe("priority-score parity", () => {
  interface Case {
    impact: number;
    ease: number;
    consensus: number;
    expected: number;
  }
  const cases = loadFixture<Case[]>("priority_cases.json");
  it("all 175 combinations", () => {
    for (const c of cases) {
      expect(
        priorityScore(c.impact, c.ease, c.consensus),
        `impact=${c.impact} ease=${c.ease} consensus=${c.consensus}`,
      ).toBeCloseTo(c.expected, 10);
    }
  });
});

describe("mechanical gate parity", () => {
  interface Case {
    gate: {
      type: string;
      max_words?: number;
      section?: string;
      line_prefix?: string;
      canonical_terms?: Record<string, string[]>;
      patterns?: string[];
    };
    text: string;
    expected: { name: string; passed: boolean; findings: string[] };
  }
  const cases = loadFixture<Case[]>("gate_cases.json");
  cases.forEach((c, i) => {
    it(`gate case ${i} (${c.gate.type})`, () => {
      const gate =
        c.gate.type === "word_count"
          ? wordCountGate(c.gate.max_words!, {
              section: c.gate.section ?? null,
              linePrefix: c.gate.line_prefix ?? null,
            })
          : c.gate.type === "term_lint"
            ? termLintGate(c.gate.canonical_terms!)
            : bannedElementsGate(c.gate.patterns!);
      expect(gate.name).toBe(c.expected.name);
      const result = runGate(gate, c.text);
      expect(result.passed).toBe(c.expected.passed);
      expect(result.findings).toEqual(c.expected.findings);
    });
  });
});

