describe("cost estimation parity", () => {
  interface Case {
    name: string;
    config: {
      models: {
        reviewers: { id: string }[];
        synthesizer: { id: string };
        drafter?: { id: string };
      };
      pipeline?: { runs_per_persona?: number };
      personas: string[];
    };
    entries: { name: string; tier: number; send_to: string[] }[];
    documents: Record<string, number>;
    system_prompt_chars: number;
    persona_overlay_chars: Record<string, number>;
    include_drafter: boolean;
    iterations: number;
    expected: {
      model_estimates: {
        model_id: string;
        num_calls: number;
        input_tokens_per_call: number;
        output_tokens_per_call: number;
        input_cost_usd: number;
        output_cost_usd: number;
      }[];
      total_usd: number;
      per_loop_usd: number;
      iterations: number;
    };
  }
  const cases = loadFixture<Case[]>("cost_cases.json");
  it.each(cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const entries: ManifestEntry[] = c.entries.map((e) => ({
      name: e.name,
      path: `/nonexistent/${e.name}`,
      format: "markdown",
      role: "",
      tier: e.tier as 1 | 2 | 3,
      sendTo: e.send_to,
      critical: false,
      notes: "",
    }));
    const documents: Record<string, DocumentModel> = Object.fromEntries(
      Object.entries(c.documents).map(([name, chars]) => [
        name,
        {
          name,
          role: "r",
          tier: c.entries.find((e) => e.name === name)!.tier,
          content: "",
          pageCount: 1,
          charCount: chars,
          sha256: "0".repeat(64),
          truncated: false,
        },
      ]),
    );
    const estimate = estimatePipelineCost({
      reviewerIds: c.config.models.reviewers.map((r) => r.id),
      synthesizerId: c.config.models.synthesizer.id,
      drafterId: c.config.models.drafter?.id ?? null,
      runsPerPersona: c.config.pipeline?.runs_per_persona ?? 2,
      personas: c.config.personas,
      personaDocChars: (persona) =>
        assembleForPersona(persona, entries, documents).map((d) => d.charCount),
      allDocChars: Object.values(documents).map((d) => d.charCount),
      systemPromptChars: c.system_prompt_chars,
      personaOverlayChars: c.persona_overlay_chars,
      includeDrafter: c.include_drafter,
      iterations: c.iterations,
    });
    expect(estimate.iterations).toBe(c.expected.iterations);
    expect(estimate.modelEstimates.length).toBe(c.expected.model_estimates.length);
    for (let i = 0; i < estimate.modelEstimates.length; i++) {
      const actual = estimate.modelEstimates[i]!;
      const exp = c.expected.model_estimates[i]!;
      expect(actual.modelId).toBe(exp.model_id);
      expect(actual.numCalls).toBe(exp.num_calls);
      expect(actual.inputTokensPerCall).toBe(exp.input_tokens_per_call);
      expect(actual.outputTokensPerCall).toBe(exp.output_tokens_per_call);
      expect(actual.inputCostUsd).toBeCloseTo(exp.input_cost_usd, 6);
      expect(actual.outputCostUsd).toBeCloseTo(exp.output_cost_usd, 6);
    }
    expect(estimateTotalUsd(estimate)).toBeCloseTo(c.expected.total_usd, 6);
    expect(estimatePerLoopUsd(estimate)).toBeCloseTo(c.expected.per_loop_usd, 6);
  });
});
